import {mountCustomBuildingLibrary} from './custom-building-library-ui.js?v=scenario-variable-manager-1';
import {importBuildingDesign,buildingDesignCanvas} from './building-designs.js?v=scenario-variable-manager-1';
export function showCustomBuildingEditor({dialog,back,storage}){
 let draft=null,rotation=0,request=0;
 dialog('Custom building list',`<p>Import and organize models for future use in any city in this browser. Preview a saved model or choose a building file, then add it to the list below.</p><label>Building file<input id="customListFile" type="file" accept=".json,application/json"></label><p id="customListStatus" role="status"></p><div><img id="customListPreview" width="192" height="288" alt="" hidden><p id="customListName"></p><div class="actions"><button id="customListLeft" disabled>Rotate left</button><span id="customListDirection" role="status"></span><button id="customListRight" disabled>Rotate right</button></div></div><div id="customListEditor"></div><div class="actions"><button id="customListBack">Back to city building styles</button></div>`);
 const $=id=>document.getElementById(id),input=$('customListFile'),status=$('customListStatus');
 const draw=()=>{if(!draft)return;const image=$('customListPreview');image.src=buildingDesignCanvas(draft,rotation).toDataURL('image/png');image.alt=draft.name;image.hidden=false;$('customListName').textContent=`${draft.name} · ${draft.footprint?.width??1} × ${draft.footprint?.height??1} tiles`;$('customListDirection').textContent=['North','East','South','West'][rotation];$('customListLeft').disabled=$('customListRight').disabled=false;};
 mountCustomBuildingLibrary({host:$('customListEditor'),storage,getDraft:()=>draft,selectDesign:model=>{request++;draft=model;draw();status.textContent='Saved model selected for preview.';}});
 $('customListEditor').querySelector('details')?.setAttribute('open','');
 input.onchange=async()=>{const file=input.files?.[0],id=++request;if(!file)return;status.textContent='Reading building file…';try{if(file.size>32768)throw Error('Building files must be smaller than 32 KB.');const model=importBuildingDesign(await file.text());if(id!==request||document.getElementById('customListFile')!==input)return;draft=model;draw();status.textContent='Model ready. Add it to the draft list, then save the list to keep it.';}catch(error){if(id===request&&document.getElementById('customListFile')===input)status.textContent=error.message||'Could not read this building file.';}finally{if(id===request)input.value='';}};
 $('customListLeft').onclick=()=>{rotation=(rotation+3)%4;draw();};$('customListRight').onclick=()=>{rotation=(rotation+1)%4;draw();};$('customListBack').onclick=()=>{request++;back();};
}
